  Vector2[] Path(CityProperty a,CityProperty b)=>new[]{Point(a.X+1,a.Y+1.44f),Point(a.X+1,a.Y+1.5f),Point(a.X+1.5f,a.Y+1.5f),Point(b.X+1.5f,a.Y+1.5f),Point(b.X+1.5f,b.Y+1.5f),Point(b.X+1,b.Y+1.5f),Point(b.X+1,b.Y+1.44f)};
  static void Cup(UnityEngine.UI.VertexHelper vh,Vector2 p){var white=new Color(1,.95f,.84f,1);CraftedPanel.Quad(vh,p+new Vector2(-5,-4),p+new Vector2(4,-4),p+new Vector2(5,4),p+new Vector2(-6,4),white);CraftedPanel.Line(vh,p+new Vector2(4,3),p+new Vector2(8,2),2,white);CraftedPanel.Line(vh,p+new Vector2(8,2),p+new Vector2(7,-2),2,white);CraftedPanel.Line(vh,p+new Vector2(-4,3),p+new Vector2(4,3),3,FlatUI.Hex("#7A442E"));}
  protected override void OnPopulateMesh(UnityEngine.UI.VertexHelper vh){vh.Clear();if(City==null||Report==null)return;float minute=(ReadProgress?.Invoke()??0)*1440;var visible=Report.Flows.Where(f=>f.Source!=0&&f.Target!=0&&(f.Kind=="CUSTOMER"||f.Kind=="COFFEE"||f.Kind=="CASH")).ToArray();foreach(var group in visible.GroupBy(f=>f.Source+":"+f.Target+":"+f.Kind)){var f=group.First();var a=City.Properties.Find(p=>p.Id==f.Source);var b=City.Properties.Find(p=>p.Id==f.Target);if(a==null||b==null)continue;var path=Path(a,b);var tint=f.Kind=="CASH"?FlatUI.Hex("#FFE562"):f.Kind=="COFFEE"?FlatUI.Hex("#F4B591"):FlatUI.Hex("#7CFFD6");float total=0;var length=new float[path.Length];for(int i=1;i<path.Length;i++){total+=Vector2.Distance(path[i-1],path[i]);length[i]=total;var segment=path[i]-path[i-1];if(segment.sqrMagnitude<1)continue;var offset=new Vector2(-segment.y,segment.x).normalized*(f.Kind=="CASH"?4:-4);var shade=tint;shade.a=.3f;CraftedPanel.Line(vh,path[i-1]+offset,path[i]+offset,1.5f,shade);}foreach(var token in group){float elapsed=minute-token.Minute,duration=Math.Max(25,token.TravelMinutes);if(elapsed<0||elapsed>duration)continue;float along=elapsed/duration*total;int part=1;while(part<path.Length-1&&length[part]<along)part++;float span=length[part]-length[part-1];var point=Vector2.Lerp(path[part-1],path[part],span<=0?1:(along-length[part-1])/span);var direction=path[part]-path[part-1];point+=new Vector2(-direction.y,direction.x).normalized*(token.Kind=="CASH"?4:-4);if(token.Kind=="COFFEE")Cup(vh,point);else if(token.Kind=="CASH")CraftedPanel.Diamond(vh,point,6,tint);else ResourceToken.Draw(vh,point,6,0);}}}
 }
